def reflex_vacuum_agent(percept):
    loc, status = percept
    if status == "สกปรก":
        return "ดูดฝุ่น"
    return "ไปขวา" if loc == "A" else "ไปซ้าย"

class ModelBasedAgent:
    def __init__(self, patience=2):
        self.patience = patience
        self.empty_count = 0
        self.ac = False

    def act(self, people, temp):
        self.empty_count = self.empty_count + 1 if people == 0 else 0
        if people > 0:
            self.ac = temp >= 26
        elif self.empty_count >= self.patience:
            self.ac = False
        return self.ac

agent = ModelBasedAgent(patience=2)
readings = [(30, 28), (0, 28), (25, 27), (0, 27), (0, 27), (0, 27)]
for i, (people, temp) in enumerate(readings, start=1):
    print(i, agent.act(people, temp))

triples = [("เพนกวิน", "is-a", "นก"), ("นก", "สามารถ", "บิน"),
           ("นก", "is-a", "สัตว์"), ("สัตว์", "is-a", "สิ่งมีชีวิต")]

def all_types(x):
    found, frontier = [], [x]
    while frontier:
        node = frontier.pop()
        for s, r, o in triples:
            if s == node and r == "is-a" and o not in found:
                found.append(o)
                frontier.append(o)
    return found

print(all_types("เพนกวิน"))
